from core.may_tinh import tinh_bieu_thuc

def dap_cau_hoi_co_phep_toan(cau_hoi):
    # Tìm vị trí của phép toán trong câu hỏi
    toan_tu = None
    for tu in ['+', '-', '*', '/']:
        if tu in cau_hoi:
            toan_tu = tu
            break

    if toan_tu is None:
        return None  # Không có phép toán trong câu hỏi

    # Tách biểu thức số học
    bieu_thuc = cau_hoi.split(toan_tu)
    if len(bieu_thuc) != 2:
        return None  # Biểu thức số học không hợp lệ

    # Tính giá trị biểu thức
    try:
        ket_qua = tinh_bieu_thuc(bieu_thuc[0].strip() + toan_tu + bieu_thuc[1].strip())
        return ket_qua
    except:
        return None  # Biểu thức số học không hợp lệ

from core.may_tinh import tinh_bieu_thuc

def lam_ra_ket_qua_day_phep(day_phep):
    ket_qua = None
    for phep in day_phep:
        ket_qua = tinh_bieu_thuc(phep)
        if ket_qua is None:
            break
    return ket_qua

